export const ROCKS=[{x:20,y:25,r:6},{x:41,y:42,r:8},{x:62,y:23,r:6},{x:28,y:66,r:7},{x:72,y:59,r:8},{x:52,y:80,r:5}];
export const TARGETS=[{id:'outcrop',name:'Layered outcrop',x:21,y:46,description:'Inspect the layering before deciding how the rock formed.'},{id:'soil',name:'Soil exposure',x:57,y:62,description:'Compare loose soil with the nearby rock surface.'},{id:'ridge',name:'Ridge station',x:84,y:34,description:'Record a contextual panorama to link your observations.'}];
export function newTraverse(mission='opportunity'){return {mission,x:10,y:12,heading:0,battery:100,distance:0,elapsed:0,samples:[],speed:0,collision:false,complete:false,ended:false,malfunction:false};}
export function stepTraverse(s,input,dt,allocation=35){if(s.ended||s.complete)return s;dt=Math.max(0,Math.min(dt,.05));const throttle=Math.max(-1,Math.min(1,input.throttle||0));const turn=Math.max(-1,Math.min(1,input.turn||0));const malfunction=s.mission==='spirit'&&s.distance>10;const desired=throttle*(malfunction?5:8)*Math.max(0,allocation/35)*(input.fast?1.35:1)*(throttle<0?.6:1);const response=throttle?1-Math.exp(-dt*3):1-Math.exp(-dt*6);const speed=s.speed+(desired-s.speed)*response;const heading=s.heading+turn*dt*(malfunction?.8:1.5);const nx=s.x+Math.sin(heading)*speed*dt,ny=s.y+Math.cos(heading)*speed*dt;const hit=nx<3||nx>97||ny<3||ny>97||ROCKS.some(r=>Math.hypot(nx-r.x,ny-r.y)<r.r+1.7);const travel=hit?0:Math.hypot(nx-s.x,ny-s.y);const battery=Math.max(0,s.battery-dt*(.035+Math.abs(speed)*.075+(hit&&throttle?.25:0)));return {...s,x:hit?s.x:nx,y:hit?s.y:ny,heading,battery,distance:s.distance+travel,elapsed:s.elapsed+dt,speed:hit?0:speed,collision:hit,malfunction,ended:battery<=0};}
export function nearestTarget(s){return TARGETS.filter(t=>!s.samples.includes(t.id)).find(t=>Math.hypot(t.x-s.x,t.y-s.y)<8)||null;}
export function observeTarget(s){const t=nearestTarget(s);if(!t||Math.abs(s.speed)>.6||s.ended||s.complete)return {state:s,message:'Stop within the marked observation radius before using the instrument.'};if(s.battery<3)return {state:s,message:'Insufficient energy for this observation.'};const samples=[...s.samples,t.id];return {state:{...s,samples,battery:s.battery-3,complete:samples.length===TARGETS.length},message:`Observation recorded: ${t.name}. ${t.description}`};}
export function landingStep(s,thrust,dt){if(s.done)return s;dt=Math.max(0,Math.min(.1,dt));const throttle=Math.max(0,Math.min(1,Number(thrust)));const burn=Math.min(s.fuel,dt*throttle*7);const fuel=s.fuel-burn;const acceleration=dt>0?burn/(dt*7)*4.2:0;const v=s.v+(1.62-acceleration)*dt;const h=Math.max(0,s.h-v*dt);return {...s,h,v,fuel,done:h===0,safe:h===0&&Math.abs(v)<2.5};}
export function pathDistance(points){return points.slice(1).reduce((s,p,i)=>s+Math.hypot(p.x-points[i].x,p.y-points[i].y),0);}
export function segmentBlocked(a,b,rocks=ROCKS){return rocks.some(r=>{const dx=b.x-a.x,dy=b.y-a.y;const t=Math.max(0,Math.min(1,((r.x-a.x)*dx+(r.y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(a.x+t*dx-r.x,a.y+t*dy-r.y)<r.r+2;});}
